// Wire types for /api/dash/*, checked field by field against src/mock/fixtures (generated by
// the real backend). Timestamps are UNIX seconds (fractional) in UTC. Phone strings are masked,
// "(656) ***-0150", unless the request carried reveal=1.
//
// `Wire*` types are what the server sends. The view types (`CallRow`, `CallDetail`) drop
// `summary` (conflict 15: test junk, never rendered); the client maps it out.

export type Disposition =
  | 'phone-booked'
  | 'phone-no-booking'
  | 'live'
  | 'unknown-crash'
  // Unknown future values render as a neutral humanized chip (lib/chips.ts).
  | (string & {})

// ---------------------------------------------------------------- /status

export interface StatusResponse {
  ok: boolean
  events: boolean
  boot_at: number
  now: number
  live_calls: number
  line: 'idle' | 'on-call'
  /** Start time of the most recent call; null when the line has never taken a call. */
  last_call_at: number | null
  /** Server-side path; never shown. */
  db_path?: string
  /** "Harborline Orthodontics (DEMO practice - fictional)"; see lib/text practiceName(). */
  practice: string
  /** Never shown (conflict 25). */
  model: string
  agent: string
}

// ---------------------------------------------------------------- /stats?days=N

export interface StatsRange {
  /** Local midnight N-1 days back, in `tz`. */
  from: number
  to: number
  days: number
  tz: string
}

export interface HourBucket {
  hour: number
  calls: number
  booked: number
}

export interface StatsResponse {
  range: StatsRange
  calls: number
  booked_calls: number
  bookings: number
  callbacks: number
  urgent: number
  sms_out: number
  sms_in: number
  avg_duration_s: number
  /** Always 24 entries, hour 0..23 in the practice tz. */
  by_hour: HourBucket[]
  dispositions: Record<string, number>
  /** ISO codes: { en: 8 } */
  languages: Record<string, number>
}

// ---------------------------------------------------------------- /calls

export interface WireCallRow {
  call_id: string
  started_at: number
  /** null while the call is live. */
  ended_at: number | null
  /** Fractional seconds; null while live. Format with lib/time formatDuration (conflict 14). */
  duration_s: number | null
  caller: string
  disposition: Disposition
  summary?: string
  bookings: number
  notes: number
  language: string
  greeted_as: string
  turns: number
  status: 'live' | 'ended'
  first_line: string
}

export interface WireCallsResponse {
  calls: WireCallRow[]
}

/** A call as the UI sees it (no `summary`). */
export type CallRow = Omit<WireCallRow, 'summary'>

// ---------------------------------------------------------------- /calls/:id

/** The detail `call` object has every row field except `first_line`. */
export type CallDetailCall = Omit<CallRow, 'first_line'> & { first_line?: string }

export interface WireCallDetailResponse {
  call: Omit<WireCallRow, 'first_line'> & { first_line?: string }
  events: CallEvent[]
}

export interface CallDetail {
  call: CallDetailCall
  events: CallEvent[]
}

// ---------------------------------------------------------------- events

export type ToolName = 'lookup' | 'context' | 'book' | 'cancel' | 'message' | (string & {})

export interface ToolData {
  name: ToolName
  ok: boolean
  ms: number
  /** lookup */
  verified?: boolean
  /** context; may be 0 right before a slot is offered (conflict 22) */
  open_slots?: number
  /** book, cancel */
  slot?: string
  /** book */
  patient?: string
  /** book */
  already_booked?: boolean
}

/** `data` payload per event kind, in the order they happen inside a call. */
export interface EventDataMap {
  'call.started': { caller: string }
  greeting: { name: string }
  'turn.caller': { text: string }
  /** Several bot events can share one `turn`: they are the sentences of one reply. */
  'turn.bot': { text: string }
  tool: ToolData
  booking: { name: string; slot: string; reason: string; insurance: string }
  note: { name: string; reason: string; urgent: boolean; fyi: boolean }
  cancel: { name: string; slot: string }
  'sms.out': { caller: string; kind: string; chars: number }
  'sms.in': { caller: string; kind: string; chars?: number }
  /** `duration_s` here disagrees with the row; always use the row's (conflict 13). */
  'call.ended': { duration_s: number; disposition: Disposition; bookings: number; notes: number }
}

export type EventKind = keyof EventDataMap

export const EVENT_KINDS: readonly EventKind[] = [
  'call.started',
  'greeting',
  'turn.caller',
  'turn.bot',
  'tool',
  'booking',
  'note',
  'cancel',
  'sms.out',
  'sms.in',
  'call.ended',
]

/** One event inside GET /calls/:id. */
export type CallEvent = {
  [K in EventKind]: { id: number; ts: number; kind: K; turn: number; data: EventDataMap[K] }
}[EventKind]

/** One SSE message on /stream (`event:` = kind, `data:` = this JSON). Same as CallEvent without `id`. */
export type DashEvent<K extends EventKind = EventKind> = {
  [P in K]: { ts: number; call_id: string; kind: P; turn: number; data: EventDataMap[P] }
}[K]

// ---------------------------------------------------------------- lists

export interface Booking {
  id: number
  ts: number
  call_id: string
  caller: string
  name: string
  /** "Mon 3:20 PM"; Katie expands it with lib/time expandSlot(). */
  slot: string
  reason: string
  /** "" or "not provided" render "Not given" (lib/text insuranceLabel). */
  insurance: string
  /**
   * True for a new patient (the chart lookup found no record), false for an existing one.
   * Only the demo data (mock=demo) sends it today; when absent, lib/reason isNewPatientBooking
   * falls back to the reason text.
   */
  new_patient?: boolean
}

export interface BookingsResponse {
  bookings: Booking[]
}

/** A desk note = a callback. */
export interface Note {
  id: number
  ts: number
  call_id: string
  caller: string
  /** May be "", or "unknown (…)": use lib/text displayName / displayIdentity. */
  name: string
  /** Carries [annotations] and "URGENT:"; render lib/text cleanReason(reason). */
  reason: string
  urgent: boolean
  fyi: boolean
}

export interface NotesResponse {
  notes: Note[]
}

export interface Sms {
  id: number
  ts: number
  call_id: string
  direction: 'in' | 'out'
  phone: string
  /** "confirmation" (out), "yes" (in), or another raw kind. */
  kind: string
  chars: number
  /**
   * The message body. Demo data (mock=demo) only: the real API never sends text bodies (PHI),
   * so real mode never has it and the UI must not depend on it.
   */
  text?: string
}

export interface SmsResponse {
  sms: Sms[]
}

// ---------------------------------------------------------------- leads (GET /leads, /leads/:id)

/** The funnel, in order. Open = the first four. */
export type LeadStage =
  | 'quoted'
  | 'consult_booked'
  | 'consult_missed'
  | 'consult_happened'
  | 'started'
  | 'lost'
  | 'paused'

export const LEAD_STAGES: readonly LeadStage[] = [
  'quoted',
  'consult_booked',
  'consult_missed',
  'consult_happened',
  'started',
  'lost',
  'paused',
]

/** `stage=` on GET /leads: the open four, a follow-up pool, one stage, or everything. */
export type LeadsFilter = 'open' | 'missed_consult' | 'never_booked' | LeadStage | 'all'

export interface LeadQuoteOption {
  /** The code: "metal", "ceramic", "aligner_comprehensive", ... */
  appliance: string
  /** The practice's words: "Metal braces". */
  label: string
  /** Dollars; null renders "—". */
  total: number | null
  insurance: number | null
  /** estimated = an amount; pending = benefits still being checked; zero = the plan pays nothing; none = no insurance given. */
  insurance_status: 'estimated' | 'pending' | 'zero' | 'none' | '' | (string & {})
  patient: number | null
  monthly: number | null
  down: number | null
}

export interface LeadQuote {
  /** The schedule's category name: "Comprehensive", "Phase1", "AdultComprehensive". */
  category: string
  /** The practice's sentence for patients (can be long); falls back to the category. */
  category_label: string
  options: LeadQuoteOption[]
  consult_fee: number | null
  currency: string
}

/** One lead: someone who got a quote and has not followed through. */
export interface LeadRow {
  /** "L" + 10 hex. Not patient data: it may appear in a URL. */
  lead_id: string
  /** The photo-consult token. NEVER rendered, logged or put in a URL. */
  token: string
  /** Never rendered. */
  practice_slug: string
  /** Masked "(813) ***-0141"; with reveal=1 the ten digits "8135550141" (lib leadPhone formats both). */
  phone: string
  /** One word. */
  first_name: string
  language: string
  /** Never rendered raw: pages/leads/model consentLabel maps it. */
  consent_basis: string
  stage: LeadStage
  stage_at: number
  /** quote_sent | call_booking | sms_reslot | sms_cancel | call_cancel | sweep | nexhealth | coordinator */
  stage_source: string
  created_at: number
  updated_at: number
  quoted_at: number | null
  quote: LeadQuote | null
  appointment_id: string
  /** ISO or the slot label, as the booking lane wrote it. Not rendered (consult_at and the label are). */
  appointment_start: string
  /** "Thu 9:00 AM" */
  appointment_label: string
  /** The exam's unix time; null = unknown (the clock never calls such a lead a no-show). */
  consult_at: number | null
  missed_reason: '' | 'no_show' | 'cancelled'
  sms_stopped_at: number | null
  last_touch_at: number | null
  /** A label, never a message body: "quote text sent", "text in: yes", "exam booked Thu 9:00 AM", "coordinator: lost". */
  last_touch: string
  /** The coordinator's one line. */
  note: string
  open: boolean
  /** missed_consult = Pool A (stage consult_missed); never_booked = quoted, no exam for a week. */
  pool: '' | 'missed_consult' | 'never_booked'
  texts_stopped: boolean

  // Reserved for the next backend pieces (the follow-up text ladder and the day-3 call prompt).
  // Optional: absent today. The page reads them through pages/leads/model nextStep(), the one
  // place to rename them when the backend lands.
  /** When the next follow-up text goes out (unix seconds), or null when none is due. */
  next_text_at?: number | null
  /** What that text is: "Day 2 text". */
  next_text_label?: string
  /** True when it is time for a person to call this lead (missed-consult rows). */
  call_now?: boolean
  /** Why now, in the desk's words: "No reply to two texts". */
  call_now_reason?: string
}

export type LeadEventKind = 'quoted' | 'stage' | 'touch' | 'sms_stop' | 'coordinator' | 'note' | 'unmatched' | 'moved'

/** One line of a lead's history (GET /leads/:id), oldest first. */
export interface LeadEvent {
  id: number
  ts: number
  kind: LeadEventKind | (string & {})
  /** stage: {from, to, source, reason, who, note, appointment_label?, consult_at?}; note: {who, note}; touch: {what, direction}. */
  data: Record<string, unknown>
}

/** Counts over every lead. The backend answers {} when the lead record is switched off. */
export interface LeadsSummary {
  by_stage?: Partial<Record<LeadStage, number>>
  open?: number
  missed_consult?: number
  never_booked?: number
  texts_stopped?: number
  total?: number
}

export interface LeadsResponse {
  leads: LeadRow[]
  summary: LeadsSummary
}

export interface LeadDetail {
  lead: LeadRow
  events: LeadEvent[]
}

/** POST /leads/:id/action. */
export type LeadAction = 'happened' | 'started' | 'lost' | 'paused' | 'reopen' | 'booked' | 'missed' | 'note'

export interface LeadActionBody {
  action: LeadAction
  /** One optional line; for `note` it is the note itself ("" clears it). */
  note?: string
  /** `booked` only: "Thu 9:00 AM" or a local ISO time "2026-11-12T09:00" (read in the practice's timezone). */
  slot_label?: string
}

/** The lead after the tap. Its phone is always masked, whatever Show numbers says. */
export interface LeadActionResponse {
  ok: true
  lead: LeadRow
}
